html:
{% set approved_by_user = doc.ts_approved_by or "" %}
{% set is_ceo = frappe.db.get_value("Has Role", {"parent": approved_by_user, "role": "CEO"}, "name") if approved_by_user else "" %}
{% set is_md = frappe.db.get_value("Has Role", {"parent": approved_by_user, "role": "MD"}, "name") if approved_by_user else "" %}
{% set is_approved = doc.ts_approval_status == "Approved" and doc.docstatus == 1 %}

<style>
@page { size: A4; margin: 8mm 10mm 8mm 10mm; }
body { font-family: Arial, sans-serif; font-size: 11px; color: #333; }
.po-page { width: 100%; }
.po-header-img { width: 100%; max-height: 80px; }
.po-title { text-align: center; margin: 8px 0 2px; font-size: 16px; font-weight: bold; text-decoration: underline; letter-spacing: 1px; }
.po-subtitle { text-align: center; font-size: 9px; font-style: italic; color: #555; margin: 2px 0; }
.po-addr { text-align: center; font-size: 8px; color: #666; margin: 1px 0 6px; }
.po-info-table { width: 100%; border-collapse: collapse; margin: 4px 0; }
.po-info-table td { padding: 3px 6px; font-size: 10px; vertical-align: top; }
.po-info-label { font-weight: bold; width: 120px; }
.po-info-val { }
.po-items { width: 100%; border-collapse: collapse; margin: 6px 0; }
.po-items th { background: #f0f0f0; border: 1px solid #999; padding: 4px 6px; font-size: 9px; text-transform: uppercase; text-align: center; font-weight: bold; }
.po-items td { border: 1px solid #ccc; padding: 3px 6px; font-size: 10px; }
.po-items .num { text-align: right; }
.po-items .ctr { text-align: center; }
.po-total-row td { font-weight: bold; border-top: 2px solid #333; }
.po-grand td { background: #e8f4fd; font-size: 12px; font-weight: bold; }
.po-terms-heading { font-size: 12px; font-weight: bold; text-decoration: underline; margin: 10px 0 4px; }
.po-terms-body { font-size: 10px; line-height: 1.6; }
.po-terms-body b { font-weight: bold; }
.po-stamp-area { margin-top: 20px; text-align: right; }
.po-stamp-img { width: 100px; height: auto; opacity: 0.85; }
.po-stamp-label { font-size: 9px; font-weight: bold; text-align: center; margin-top: 2px; }
.po-footer-img { width: 100%; max-height: 70px; margin-top: 10px; }
.po-footer-text { text-align: center; font-size: 8px; color: #555; margin-top: 4px; }
.po-sig-line { border-top: 1px solid #333; width: 150px; margin: 30px 0 2px auto; }
.po-sig-label { text-align: right; font-size: 9px; font-weight: bold; }
.po-draft-watermark { position: fixed; top: 40%; left: 20%; font-size: 80px; color: rgba(255,0,0,0.06); font-weight: bold; transform: rotate(-35deg); z-index: -1; letter-spacing: 15px; }
.po-payment-table { width: 100%; border-collapse: collapse; margin: 6px 0; }
.po-payment-table th { background: #f0f0f0; border: 1px solid #999; padding: 3px 6px; font-size: 9px; text-transform: uppercase; font-weight: bold; }
.po-payment-table td { border: 1px solid #ccc; padding: 3px 6px; font-size: 10px; }
.page-break { page-break-before: always; }
</style>

{% if not is_approved %}
<div class="po-draft-watermark">DRAFT</div>
{% endif %}

<div class="po-page">

<!-- HEADER IMAGE -->
<table style="width:100%"><tr><td>
<img src="/files/Header.png" class="po-header-img" onerror="this.style.display='none'">
</td></tr></table>

<!-- TITLE -->
<div class="po-title">PURCHASE ORDER</div>
<div class="po-subtitle">Kindly despatch your original documents to our office</div>
<div class="po-addr">Khasra No. 49/1, 49/2, 49/3, 509/1 &amp; 510/2, Khasara Road, Bodijunawani, Betul, Madhya Pradesh - 460001</div>
<div class="po-addr">Email: purchase.catitions@betulbiofuel.com</div>

<!-- PO INFO -->
<table class="po-info-table" style="border:1px solid #ccc;">
<tr>
  <td class="po-info-label">Purchase Order #</td>
  <td class="po-info-val"><b>{{ doc.name }}</b></td>
  <td class="po-info-label">Date</td>
  <td class="po-info-val">{{ frappe.format(doc.transaction_date, {"fieldtype": "Date"}) }}</td>
</tr>
<tr>
  <td class="po-info-label">Supplier</td>
  <td class="po-info-val" colspan="3">{{ doc.supplier_name or doc.supplier }}</td>
</tr>
<tr>
  <td class="po-info-label">Address</td>
  <td class="po-info-val">
    {% set addr = frappe.get_doc("Address", doc.supplier_address) if doc.supplier_address else none %}
    {% if addr %}{{ addr.address_line1 or "" }}{% if addr.address_line2 %}, {{ addr.address_line2 }}{% endif %}{% if addr.city %}, {{ addr.city }}{% endif %}{% if addr.state %}, {{ addr.state }}{% endif %} {{ addr.pincode or "" }}{% endif %}
  </td>
  <td class="po-info-label">Required By</td>
  <td class="po-info-val">{{ frappe.format(doc.schedule_date, {"fieldtype": "Date"}) if doc.schedule_date else "" }}</td>
</tr>
<tr>
  <td class="po-info-label">Delivery Address</td>
  <td class="po-info-val" colspan="3">
    {% set del_addr = frappe.get_doc("Address", doc.shipping_address) if doc.shipping_address else none %}
    {% if del_addr %}{{ del_addr.address_line1 or "" }}{% if del_addr.city %}, {{ del_addr.city }}{% endif %}{% if del_addr.state %}, {{ del_addr.state }}{% endif %} {{ del_addr.pincode or "" }}{% else %}Khasara Road, Bodijunawani, Betul, Madhya Pradesh 460001{% endif %}
  </td>
</tr>
<tr>
  <td class="po-info-label">Contact</td>
  <td class="po-info-val">{{ doc.contact_display or "" }}</td>
  <td class="po-info-label">Cost Center</td>
  <td class="po-info-val">{{ doc.cost_center or "" }}</td>
</tr>
<tr>
  <td class="po-info-label">Project</td>
  <td class="po-info-val">{{ doc.ts_project or doc.project or "" }}</td>
  <td class="po-info-label">Material Request</td>
  <td class="po-info-val">
    {% set mr_ref = "" %}
    {% for item in doc.items %}{% if item.material_request and not mr_ref %}{% set mr_ref = item.material_request %}{% endif %}{% endfor %}
    {{ mr_ref }}
  </td>
</tr>
</table>

<!-- ITEMS TABLE -->
<table class="po-items">
<thead>
<tr>
  <th style="width:30px">S.No</th>
  <th>Item</th>
  <th style="width:65px">Quantity</th>
  <th style="width:50px">Unit</th>
  <th style="width:70px">Rate</th>
  <th style="width:50px">GST %</th>
  <th style="width:85px">Amount</th>
</tr>
</thead>
<tbody>
{% for item in doc.items %}
<tr>
  <td class="ctr">{{ loop.index }}</td>
  <td>{{ item.item_name or item.item_code }}{% if item.description and item.description != item.item_name %}<br><span style="font-size:8px;color:#888;">{{ item.description[:80] }}</span>{% endif %}</td>
  <td class="num">{{ frappe.format(item.qty, {"fieldtype": "Float", "precision": 2}) }}</td>
  <td class="ctr">{{ item.uom or item.stock_uom }}</td>
  <td class="num">{{ frappe.format(item.rate, {"fieldtype": "Currency"}) }}</td>
  <td class="ctr">{% set tax_rate = frappe.db.get_value("Item Tax Template Detail", {"parent": item.item_tax_template, "idx": 1}, "tax_rate") if item.item_tax_template else 0 %}{{ tax_rate or "" }}</td>
  <td class="num">{{ frappe.format(item.amount, {"fieldtype": "Currency"}) }}</td>
</tr>
{% endfor %}
</tbody>
<tfoot>
<tr>
  <td colspan="6" class="num"><b>Net Total</b></td>
  <td class="num"><b>{{ frappe.format(doc.net_total, {"fieldtype": "Currency"}) }}</b></td>
</tr>
{% for tax in doc.taxes %}
<tr>
  <td colspan="6" class="num">{{ tax.description }}</td>
  <td class="num">{{ frappe.format(tax.tax_amount, {"fieldtype": "Currency"}) }}</td>
</tr>
{% endfor %}
{% if not doc.taxes %}
<tr>
  <td colspan="6" class="num">Total Taxes and Charges</td>
  <td class="num">{{ frappe.format(0, {"fieldtype": "Currency"}) }}</td>
</tr>
{% endif %}
<tr class="po-grand">
  <td colspan="6" class="num">Grand Total</td>
  <td class="num">{{ frappe.format(doc.grand_total, {"fieldtype": "Currency"}) }}</td>
</tr>
</tfoot>
</table>

<!-- PAYMENT TERMS -->
{% if doc.payment_terms_template or doc.payment_schedule %}
<div style="font-size:11px; font-weight:bold; margin:8px 0 2px; text-decoration:underline;">Payment Terms</div>
<table class="po-payment-table">
<thead>
<tr>
  <th>Due Date</th>
  <th>Description</th>
  <th>Invoice Portion</th>
  <th>Amount Payable</th>
</tr>
</thead>
<tbody>
{% for ps in doc.payment_schedule %}
<tr>
  <td>{{ frappe.format(ps.due_date, {"fieldtype": "Date"}) }}</td>
  <td>{{ ps.payment_term or "" }}</td>
  <td class="num">{{ ps.invoice_portion }}%</td>
  <td class="num">{{ frappe.format(ps.payment_amount, {"fieldtype": "Currency"}) }}</td>
</tr>
{% endfor %}
</tbody>
</table>
{% endif %}

<!-- PAGE BREAK for Terms -->
<div class="page-break"></div>

<!-- TERMS AND CONDITIONS -->
{% if doc.tc_name or doc.terms %}
<div class="po-terms-heading">Terms and Conditions</div>
<div class="po-terms-body">{{ doc.terms or "" }}</div>
{% endif %}

<!-- REMARKS -->
{% if doc.ts_remark %}
<div style="margin-top:8px;">
<div class="po-terms-heading">Remarks</div>
<div class="po-terms-body">{{ doc.ts_remark }}</div>
</div>
{% endif %}

<!-- STAMP / SIGNATURE -->
<div class="po-stamp-area">
{% if is_approved and is_ceo %}
  <img src="/files/CEO.jpeg" class="po-stamp-img">
  <div class="po-stamp-label">CEO</div>
{% elif is_approved and is_md %}
  <img src="/files/MD.jpeg" class="po-stamp-img">
  <div class="po-stamp-label">Managing Director</div>
{% else %}
  <div class="po-sig-line"></div>
  <div class="po-sig-label">Authority Signature</div>
{% endif %}
</div>

<!-- FOOTER -->
<table style="width:100%; margin-top:15px;"><tr><td>
<img src="/files/footer.png" class="po-footer-img" onerror="this.style.display='none'">
</td></tr></table>
<div class="po-footer-text">
<b>AUTH. SIGNATORY</b><br>
<b>KINDLY DESPATCH YOUR ORIGINAL DOCUMENTS TO OUR OFFICE</b><br>
2nd Floor, LIC Building, Gurudwara Road, Betul, Ganj, Betul – 460001<br>
MOBILE NO. 7999844563<br>
E-mail: purchasemanager@betulbiofuel.com
</div>

</div>
